def min_transpositions(matrix, N):
    target = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            target[i][j] = (i * N) + j + 1

    def is_sorted(matrix):
        for i in range(N):
            for j in range(N):
                if matrix[i][j] != target[i][j]:
                    return False
        return True

    def transpose(matrix, L):
        for i in range(L):
            for j in range(i + 1, L):
                matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    if is_sorted(matrix):
        return 0

    for L in range(1, N + 1):
        temp_matrix = [row[:] for row in matrix]
        transpose(temp_matrix, L)
        if is_sorted(temp_matrix):
            return 1

    return 2

